let BACKEND_CHATBOT_CHAT_SESSION_API_ENDPOINT="/api/chats";async function getChatHistory(e){var o=new URLSearchParams(window.location.search).get("sID");if(o){e=e.backendUrl||"http://localhost:8001";try{var a=await fetch(""+e+BACKEND_CHATBOT_CHAT_SESSION_API_ENDPOINT+`/sessions/${o}/history`,{method:"GET",headers:{"Content-Type":"application/json"}});if(!a.ok)throw new Error("HTTP error! status: "+a.status);var r=await a.json();r&&r.response?r.response.forEach(e=>{var o=document.getElementById(e.variable);o?o.value=e.answer:console.warn(`Element with ID '${e.variable}' not found`)}):console.error("Invalid response format")}catch(e){console.error("Error fetching data:",e)}}else console.warn("No session ID found in URL parameters")}window.getChatHistory=getChatHistory;